// Appels Microsoft réservés au serveur. Aucun jeton ni secret dans les erreurs.
export function createGraphClient(env = process.env, request = fetch) {
  const required = ['MS_TENANT_ID', 'MS_CLIENT_ID', 'MS_CLIENT_SECRET', 'BOOKINGS_BUSINESS_ID', 'BOOKINGS_SERVICE_ID']
  if (required.some(key => !env[key])) throw new Error('BOOKING_NOT_CONFIGURED')
  const root = 'https://graph.microsoft.com/v1.0/solutions/bookingBusinesses/' + encodeURIComponent(env.BOOKINGS_BUSINESS_ID)
  let cachedToken, expiresAt = 0, pendingToken

  async function token() {
    if (cachedToken && Date.now() < expiresAt) return cachedToken
    if (!pendingToken) pendingToken = (async () => {
      const response = await request(`https://login.microsoftonline.com/${encodeURIComponent(env.MS_TENANT_ID)}/oauth2/v2.0/token`, {
        method: 'POST', signal: AbortSignal.timeout(15000),
        body: new URLSearchParams({ client_id: env.MS_CLIENT_ID, client_secret: env.MS_CLIENT_SECRET,
          scope: 'https://graph.microsoft.com/.default', grant_type: 'client_credentials' })
      })
      if (!response.ok) throw new Error(`MICROSOFT_AUTH_${response.status}`)
      const data = await response.json()
      if (!data.access_token || !Number.isFinite(data.expires_in)) throw new Error('MICROSOFT_AUTH_INVALID')
      cachedToken = data.access_token
      expiresAt = Date.now() + Math.max(0, data.expires_in - 60) * 1000
      return cachedToken
    })().finally(() => { pendingToken = null })
    return pendingToken
  }

  async function call(route, body, method) {
    // Aucune relance automatique des créations : une réponse perdue peut cacher un rendez-vous créé.
    const response = await request(root + route, {
      method: method || (body === undefined ? 'GET' : 'POST'), signal: AbortSignal.timeout(20000),
      headers: { Authorization: `Bearer ${await token()}`, 'Content-Type': 'application/json' },
      ...(body === undefined ? {} : { body: JSON.stringify(body) })
    })
    if (!response.ok) {
      const data = await response.json().catch(() => ({}))
      const error = new Error(`MICROSOFT_GRAPH_${response.status}`)
      error.diagnostic = String(data.error?.message || data.error?.code || 'Sans détail').replaceAll(env.MS_CLIENT_SECRET, '[MASQUE]').slice(0, 1500)
      throw error
    }
    if (response.status === 204) return null
    return response.json()
  }

  return {
    call,
    async configuration() {
      const results = await Promise.allSettled([
        call(''), call('/services/' + encodeURIComponent(env.BOOKINGS_SERVICE_ID)), call('/staffMembers')
      ])
      const failed = results.find(result => result.status === 'rejected')
      if (failed) throw failed.reason
      const [business, service, staff] = results.map(result => result.value)
      if (staff['@odata.nextLink']) throw new Error('STAFF_PAGINATION_REQUIRES_REVIEW')
      return { business, service, staff: staff.value }
    }
  }
}

