import { mkdirSync, readFileSync, writeFileSync, renameSync, rmdirSync, existsSync } from 'node:fs'
import path from 'node:path'
import { randomUUID } from 'node:crypto'
import { overlaps } from './schedule.js'

// Petit registre persistant : conserve les demandes incertaines après un redémarrage.
// Aucun nom, adresse, téléphone ou email n'est enregistré ici.
export function createLedger(directory) {
  mkdirSync(directory, { recursive: true, mode: 0o700 })
  const file = path.join(directory, 'requests.json')
  const lock = path.join(directory, 'reservation.lock')
  function read() {
    if (!existsSync(file)) return {}
    return JSON.parse(readFileSync(file, 'utf8'))
  }
  function write(data) {
    const temp = file + '.' + randomUUID()
    writeFileSync(temp, JSON.stringify(data), { mode: 0o600, flag: 'wx' })
    renameSync(temp, file)
  }
  function active(data, now) {
    return Object.values(data).filter(r => r.state !== 'cancelled' && r.end > now && (r.state !== 'confirmed' || now - r.updated < 15 * 60000))
  }
  return {
    holds: () => active(read(), Date.now()),
    async exclusive(run) {
      try { mkdirSync(lock, { mode: 0o700 }) } catch (error) {
        if (error.code === 'EEXIST') throw new Error('BOOKING_LOCKED')
        throw error
      }
      // Si le processus est interrompu, le verrou est conservé et doit être vérifié.
      try {
        const data = read()
        const now = Date.now()
        for (const [key, value] of Object.entries(data)) if (value.end < now - 86400000) delete data[key]
        return await run({
          get: key => data[key],
          holds: () => active(data, Date.now()),
          reserve(key, record) {
            if (active(data, Date.now()).some(r => r.staffId === record.staffId && overlaps(r, record))) throw new Error('SLOT_UNAVAILABLE')
            data[key] = { ...record, state: 'pending', updated: Date.now() }
            write(data)
          },
          cancellation(key, state) {
            if (!['cancelling','cancelled','cancel_review'].includes(state) || !data[key]) throw new Error('INVALID_CANCELLATION_STATE')
            data[key] = { ...data[key], state, updated: Date.now() }
            write(data)
          },
          confirm(key, appointmentId) {
            data[key] = { ...data[key], state: 'confirmed', appointmentId, updated: Date.now() }
            write(data)
          }
        })
      } finally { rmdirSync(lock) }
    }
  }
}

