import { managementLink } from './cancellation.js'
// LIMETTA_CUSTOM_EMAIL_V1
import { createConfirmationMailer } from './confirmation-email.js'
import { createHmac, timingSafeEqual } from 'node:crypto'
import { calculateSlots, dateAt, duration, graphTime, instant, localTime, nextDate, policyFor, validDate } from './schedule.js'

const equal = (a, b) => typeof a === 'string' && typeof b === 'string' && Buffer.byteLength(a) === Buffer.byteLength(b) && timingSafeEqual(Buffer.from(a), Buffer.from(b))
export function createBookingService(graph, ledger, secret, now = Date.now, mailer = createConfirmationMailer()) {
  const sign = value => createHmac('sha256', secret).update(value).digest('base64url')
  function seal(slot) {
    const body = Buffer.from(JSON.stringify({ staffId: slot.staffId, start: slot.start, expires: now() + 15 * 60000 })).toString('base64url')
    return `${body}.${sign(body)}`
  }
  function unseal(token) {
    if (typeof token !== 'string' || token.length > 1500) throw new Error('INVALID_SLOT')
    const [body, signature, extra] = token.split('.')
    if (extra || !equal(signature, sign(body))) throw new Error('INVALID_SLOT')
    const slot = JSON.parse(Buffer.from(body, 'base64url').toString())
    if (!Number.isFinite(slot.start) || !Number.isFinite(slot.expires) || typeof slot.staffId !== 'string') throw new Error('INVALID_SLOT')
    return slot
  }
  async function load(date, holds) {
    if (!validDate(date)) throw new Error('INVALID_DATE')
    const midnight = localTime(date, '00:00:00')
    if (midnight < now() - 86400000 || midnight > now() + 366 * 86400000) throw new Error('INVALID_DATE')
    const config = await graph.configuration()
    if (!config.service.staffMemberIds?.length) throw new Error('NO_STAFF_ASSIGNED')
    const availability = await graph.call('/getStaffAvailability', {
      staffIds: config.service.staffMemberIds,
      startDateTime: graphTime(midnight),
      endDateTime: graphTime(localTime(nextDate(date), '00:00:00'))
    })
    const query = new URLSearchParams({ start: new Date(midnight - 86400000).toISOString(), end: new Date(midnight + 2 * 86400000).toISOString() })
    const appointments = await graph.call('/calendarView?' + query)
    if (!Array.isArray(appointments.value) || appointments['@odata.nextLink']) throw new Error('CALENDAR_RESPONSE_REQUIRES_REVIEW')
    const reserved = appointments.value.flatMap(a => (a.staffMemberIds || []).map(staffId => ({
      staffId, start: instant(a.startDateTime || a.start) - duration(a.preBuffer || 'PT0S'),
      end: instant(a.endDateTime || a.end) + duration(a.postBuffer || 'PT0S')
    })))
    return { config, slots: calculateSlots(config, availability, date, now(), [...holds, ...reserved]) }
  }
  return {
    async availability(date) {
      const { slots } = await load(date, ledger.holds())
      const unique = slots.filter((slot, i) => i === 0 || slots[i - 1].start !== slot.start)
      return { slots: unique.map(slot => ({ id: seal(slot), start: new Date(slot.start).toISOString() })) }
    },
    async book(body) {
      if (!body || typeof body !== 'object') throw new Error('INVALID_CUSTOMER')
      const customer = {}
      for (const [key, max] of Object.entries({ name: 120, email: 254, phone: 30, address: 500, notes: 2000 })) {
        if (typeof body[key] !== 'string' || body[key].length > max) throw new Error('INVALID_CUSTOMER')
        customer[key] = body[key].trim()
        if (/[<>\x00-\x08\x0b\x0c\x0e-\x1f]/.test(customer[key])) throw new Error('INVALID_CUSTOMER')
      }
      if (!customer.name || !customer.address || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(customer.email) || !/^[+()\d .-]{6,30}$/.test(customer.phone)) throw new Error('INVALID_CUSTOMER')
      if (!/^[0-9a-f-]{36}$/i.test(body.requestId || '')) throw new Error('INVALID_REQUEST_ID')
      const selected = unseal(body.slotId)
      const fingerprint = sign(JSON.stringify({ customer, start: selected.start, staffId: selected.staffId }))
      return ledger.exclusive(async tx => {
        const previous = tx.get(body.requestId)
        if (previous) {
          if (!equal(previous.fingerprint, fingerprint)) throw new Error('INVALID_REQUEST_ID')
          if (previous.state === 'confirmed') return { confirmed: true, start: new Date(selected.start).toISOString() }
          throw new Error('BOOKING_UNCERTAIN')
        }
        if (selected.expires < now()) throw new Error('SLOT_EXPIRED')
        const { config, slots } = await load(dateAt(selected.start), tx.holds())
        const slot = slots.find(s => s.start === selected.start && s.staffId === selected.staffId)
        if (!slot) throw new Error('SLOT_UNAVAILABLE')
        const s = config.service, policy = policyFor(config)
        if (s.customQuestions?.some(q => q.isRequired)) throw new Error('CUSTOM_QUESTIONS_REQUIRE_REVIEW')
        if (mailer) {
          if (policy.isMeetingInviteToCustomersEnabled !== false) throw new Error('BOOKING_DISABLE_EXTRA_INVITATION')
          await mailer.prepare(body.requestId, { name:customer.name, email:customer.email, address:customer.address, start:new Date(slot.start).toISOString(), end:new Date(slot.end).toISOString() })
        }
        tx.reserve(body.requestId, { fingerprint, staffId: slot.staffId, start: slot.busyStart, end: slot.busyEnd })
        // L'enregistrement pending précède l'appel réseau pour résister à une réponse perdue.
        try {
          const appointment = await graph.call('/appointments', {
            '@odata.type': '#microsoft.graph.bookingAppointment',
            serviceId: s.id, serviceName: s.displayName,
            ...(process.env.BOOKINGS_OWNER_MANAGEMENT === 'true' ? { serviceNotes: 'Gestion privée Jordan — ne pas transférer : ' + managementLink(body.requestId) } : {}),
            startDateTime: graphTime(slot.start), endDateTime: graphTime(slot.end),
            preBuffer: s.preBuffer || 'PT0S', postBuffer: s.postBuffer || 'PT0S',
            staffMemberIds: [slot.staffId], maximumAttendeesCount: 1,
            customerTimeZone: 'Europe/Paris', isLocationOnline: false,
            serviceLocation: { displayName: customer.address },
            price: s.defaultPrice, priceType: s.defaultPriceType,
            reminders: s.defaultReminders || [],
            isCustomerAllowedToManageBooking: s.isCustomerAllowedToManageBooking ?? true,
            optOutOfCustomerEmail: Boolean(mailer),
            customers: [{ '@odata.type': '#microsoft.graph.bookingCustomerInformation', name: customer.name, emailAddress: customer.email, phone: customer.phone,
              notes: customer.notes, timeZone: 'Europe/Paris', location: { displayName: customer.address } }]
          })
          if (!appointment.id) throw new Error('MISSING_APPOINTMENT_ID')
          tx.confirm(body.requestId, appointment.id)
          if (mailer) { try { mailer.wake() } catch { console.error('[BOOKING_EMAIL] QUEUE_WAKE_FAILED') } }
          return { confirmed: true, start: new Date(slot.start).toISOString() }
        } catch (error) {
          const code = /^[A-Z_0-9]+$/.test(error.message) ? error.message : error.code
          console.error('[BOOKING_CAUSE]', typeof code === 'string' && /^[A-Z_0-9]+$/.test(code) ? code : 'UPSTREAM_OR_STORAGE_FAILURE')
          if (error.diagnostic) {
            let detail = error.diagnostic
            for (const value of Object.values(customer)) if (value) detail = detail.replaceAll(value, '[CLIENT]')
            console.error('[BOOKING_DETAIL]', detail.replace(/[\r\n]/g, ' '))
          }
          throw new Error('BOOKING_UNCERTAIN')
        }
      })
    }
  }
}

