import { createCancellationMailer } from './cancellation-email.js'
import { createCancellationService, installManagementRoutes } from './cancellation.js'
import express from 'express'
import { fileURLToPath } from 'node:url'
import { createGraphClient } from './graph.js'
import { createLedger } from './ledger.js'
import { createBookingService } from './service.js'

export function createBookingRouter(env = process.env) {
  const router = express.Router(), limits = new Map()
  let service
  function getService() {
    if (!service) service = createBookingService(createGraphClient(env),
      createLedger(fileURLToPath(new URL('../.booking-state/', import.meta.url))), env.MS_CLIENT_SECRET)
    return service
  }
  router.use((req, res, next) => {
    res.set('Cache-Control', 'no-store')
    res.set('X-Content-Type-Options', 'nosniff')
    const now = Date.now()
    for (const [key, limit] of limits) if (limit.until < now) limits.delete(key)
    const key = `${req.socket.remoteAddress}:${req.method}` // Ne pas faire confiance à X-Forwarded-For sans config du proxy.
    const limit = limits.get(key) || { count: 0, until: now + 60000 }
    if (++limit.count > (req.method === 'POST' ? 6 : 60) || limits.size > 2000) return res.status(429).json({ error: 'RATE_LIMITED' })
    limits.set(key, limit)
    next()
  })
  function failure(error, res) {
    const code = error.message
    const invalid = ['INVALID_DATE', 'INVALID_CUSTOMER', 'INVALID_SLOT', 'INVALID_REQUEST_ID']
    const conflict = ['SLOT_UNAVAILABLE', 'SLOT_EXPIRED']
    if (invalid.includes(code)) return res.status(400).json({ error: code })
    if (conflict.includes(code)) return res.status(409).json({ error: code })
    // Seulement des codes maîtrisés dans les logs, jamais le corps Microsoft ou les coordonnées.
    console.error('[BOOKING]', /^[A-Z_0-9]+$/.test(code) ? code : 'UPSTREAM_FAILURE')
    res.status(503).json({ error: ['BOOKING_UNCERTAIN', 'BOOKING_LOCKED'].includes(code) ? code : 'BOOKING_UNAVAILABLE' })
  }
  router.get('/availability', async (req, res) => {
    try { res.json(await getService().availability(req.query.date)) } catch (error) { failure(error, res) }
  })
  router.post('/appointments', async (req, res) => {
    const expectedOrigin = env.BOOKINGS_SITE_ORIGIN || 'https://cuisines-limetta.com'
    if (req.headers.origin !== expectedOrigin || req.headers['sec-fetch-site'] === 'cross-site') return res.status(403).json({ error: 'ORIGIN_REJECTED' })
    if (!req.is('application/json')) return res.status(415).json({ error: 'JSON_REQUIRED' })
    if (env.BOOKINGS_ALLOW_WRITES !== 'true') return res.status(503).json({ error: 'BOOKING_TEST_MODE' })
    try { res.json(await getService().book(req.body)) } catch (error) { failure(error, res) }
  })
  let cancellation
  const cancellationMailer = env.BOOKINGS_OWNER_MANAGEMENT === 'true' ? createCancellationMailer(env) : null
  installManagementRoutes(router, () => cancellation ||= createCancellationService(createGraphClient(env), createLedger(fileURLToPath(new URL('../.booking-state/', import.meta.url))), env, Date.now, cancellationMailer), env)
  return router
}

