// LIMETTA_MICROSOFT_MAIL_V1
import { createOwnerNotifier } from './owner-notification.js'
import { createCalendarLink } from './calendar-link.js'
import { createMailTransport, mailSender } from './mail-transport.js'
import { existsSync, mkdirSync, readFileSync, readdirSync, renameSync, writeFileSync, unlinkSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { renderConfirmation, calendarAttachment } from './email-template.js'

const root = fileURLToPath(new URL('../', import.meta.url))
const safeId = id => /^[a-f0-9-]{36}$/i.test(id)
export const smtpTransport = createMailTransport // Compatibilité des anciens scripts de contrôle.

export function buildMessage(data, key, site, logo, sender, created, env = process.env) {
  return { from:{ name:'Cuisine Limetta', address:sender }, to:{ name:data.name, address:data.email },
    replyTo:{ name:'Jordan Bayonas — Cuisine Limetta', address:site.emailContact },
    ...renderConfirmation(data, site, 'cid:limetta-logo', createCalendarLink(data,key,env,created)), messageId:`<reservation-${key}@cuisines-limetta.com>`,
    attachments:[{ filename:'logo-limetta.png', content:logo, contentType:'image/png', cid:'limetta-logo' },
      { filename:'rendez-vous-limetta.ics', content:calendarAttachment(data,key,created), contentType:'text/calendar; charset=utf-8; method=PUBLISH', contentDisposition:'attachment' }],
    disableFileAccess:true, disableUrlAccess:true }
}

export function createConfirmationMailer(env = process.env, options = {}) {
  if (env.BOOKINGS_CUSTOM_EMAIL !== 'true') return null
  const dir = options.directory || path.join(root,'.booking-state','email')
  const ledgerPath = options.ledgerPath || path.join(root,'.booking-state','requests.json')
  const site = options.site || JSON.parse(readFileSync(path.join(root,'content.json'),'utf8')).site
  const logo = options.logo || readFileSync(new URL('./email-logo.png',import.meta.url))
  const transport = options.transport || createMailTransport(env)
  const now = options.now || Date.now
  mkdirSync(dir,{ recursive:true, mode:0o700 })
  const ownerNotifier = createOwnerNotifier({directory:dir, ledgerPath, transport, env, owner:env.BOOKINGS_OWNER_EMAIL || site.emailContact, now})
  let running = false, verifiedAt = 0
  const pending = key => path.join(dir,key+'.pending.json')
  const report = (key,state) => console.error('[BOOKING_EMAIL]',key,state)
  async function flush() {
    if (running) return
    running = true
    try {
      const ledger = existsSync(ledgerPath) ? JSON.parse(readFileSync(ledgerPath,'utf8')) : {}
      for (const name of readdirSync(dir)) {
        const match = name.match(/^([a-f0-9-]{36})\.(pending|sending|review|accepted)\.json$/i)
        if (!match) continue
        const [,key,state] = match, file = path.join(dir,name)
        const entry = JSON.parse(readFileSync(file,'utf8'))
        // Ne conserver les coordonnées dans cette file que sept jours maximum.
        if (now()-entry.created > 7*86400000) { unlinkSync(file); if (state !== 'accepted') report(key,'EXPIRED_REQUIRES_REVIEW'); continue }
        if (state !== 'pending' || ledger[key]?.state !== 'confirmed') continue
        if (new Date(entry.data.end).getTime() <= now()) { unlinkSync(file); report(key,'PAST_APPOINTMENT_NOT_SENT'); continue }
        const sending = path.join(dir,key+'.sending.json')
        try { renameSync(file,sending) } catch (e) { if (e.code === 'ENOENT') continue; throw e }
        // Un .sending après interruption ne sera jamais relancé automatiquement.
        try {
          const result = await transport.sendMail(buildMessage(entry.data,key,site,logo,mailSender(env),entry.created,env))
          if (!result.accepted?.length || result.rejected?.length) throw new Error('MAIL_NOT_ACCEPTED')
          writeFileSync(path.join(dir,key+'.accepted.json'),JSON.stringify({ created:entry.created, acceptedAt:now() }),{ mode:0o600 })
          unlinkSync(sending)
          console.log('[BOOKING_EMAIL]',key,'ACCEPTED_BY_PROVIDER')
        } catch {
          // Un timeout peut cacher un envoi réussi : revue manuelle, pas de doublon automatique.
          renameSync(sending,path.join(dir,key+'.review.json'))
          report(key,'REQUIRES_REVIEW')
        }
      }
      await ownerNotifier?.flush()
    } finally { running = false }
  }
  const wake = () => { void flush().catch(() => report('QUEUE','STORAGE_REQUIRES_REVIEW')) }
  const timer = options.auto === false ? null : setInterval(wake,30000)
  timer?.unref()
  if (options.auto !== false) wake()
  return {
    async prepare(key,data) {
      if (!safeId(key)) throw new Error('INVALID_REQUEST_ID')
      if (now()-verifiedAt > 60000) {
        try { await transport.verify(); verifiedAt = now() } catch { throw new Error('BOOKING_MAIL_UNAVAILABLE') }
      }
      // Vérifier le rendu avant toute création de rendez-vous Microsoft.
      buildMessage(data,key,site,logo,mailSender(env),now(),env)
      for (const state of ['pending','sending','review','accepted']) {
        if (!existsSync(path.join(dir,key+'.'+state+'.json'))) continue
        if (state === 'pending') {
          const old = JSON.parse(readFileSync(pending(key),'utf8'))
          if (JSON.stringify(old.data) === JSON.stringify(data)) return
        }
        throw new Error('INVALID_REQUEST_ID')
      }
      ownerNotifier?.prepare(key,data)
      writeFileSync(pending(key),JSON.stringify({ created:now(), data }),{ flag:'wx', mode:0o600 })
    },
    wake, flush,
    close() { if (timer) clearInterval(timer); transport.close?.() }
  }
}

