import { createHmac, timingSafeEqual } from 'node:crypto'
import { instant } from './schedule.js'

export const escapeHtml = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))
const uuid = /^[a-f0-9-]{36}$/i
const equal = (a,b) => typeof a==='string' && Buffer.byteLength(a)===Buffer.byteLength(b) && timingSafeEqual(Buffer.from(a),Buffer.from(b))
const mac = (s,env) => { if(!env.MS_CLIENT_SECRET)throw Error('MANAGEMENT_NOT_CONFIGURED'); return createHmac('sha256',env.MS_CLIENT_SECRET).update('limetta-owner-cancel-v1:'+s).digest('base64url') }
export function managementToken(key,env=process.env) {
  if(!uuid.test(key))throw Error('INVALID_MANAGEMENT_LINK')
  return key+'.'+mac(key,env)
}
export function managementLink(key,env=process.env) {
  const origin=env.BOOKINGS_SITE_ORIGIN || 'https://cuisines-limetta.com'
  if(new URL(origin).origin!==origin || !origin.startsWith('https://'))throw Error('INVALID_MANAGEMENT_ORIGIN')
  return origin+'/api/booking/manage/'+managementToken(key,env)
}
function keyFrom(token,env) {
  if(typeof token!=='string'||token.length>100)throw Error('INVALID_MANAGEMENT_LINK')
  const [key,sig,extra]=token.split('.')
  if(extra||!uuid.test(key)||!equal(sig,mac(key,env)))throw Error('INVALID_MANAGEMENT_LINK')
  return key
}
export const appointmentLabel = data => new Intl.DateTimeFormat('fr-FR',{timeZone:'Europe/Paris',dateStyle:'full',timeStyle:'short'}).format(new Date(data.start))
export function cancellationText(data,reason='') {
  return `Bonjour ${data.name},\n\nJe vous confirme l’annulation de notre rendez-vous du ${appointmentLabel(data)}.\n\n${reason ? reason+'\n\n' : ''}Si vous souhaitez poursuivre votre projet, vous pouvez choisir un nouveau créneau ici :\nhttps://cuisines-limetta.com/rdv#reservation\n\nVous pouvez aussi me contacter au 07 67 01 21 02 ou à j.bayonas@cuisines-limetta.com pour en discuter.\n\nÀ bientôt,\nJordan Bayonas\nCuisines Limetta\nÀ vos côtés, sans pépins.`
}
export function createCancellationService(graph,ledger,env=process.env,now=Date.now,mailer) {
  function record(token,tx) {
    const key=keyFrom(token,env), r=tx.get(key)
    if(!r?.appointmentId || r.end<=now())throw Error('MANAGEMENT_LINK_EXPIRED')
    return {key,r}
  }
  async function details(r) {
    const a=await graph.call('/appointments/'+encodeURIComponent(r.appointmentId))
    if(a.serviceId!==env.BOOKINGS_SERVICE_ID || a.customers?.length!==1 || a.maximumAttendeesCount!==1)throw Error('APPOINTMENT_REQUIRES_REVIEW')
    if(a.isCancelled||a.isCanceled)throw Error('APPOINTMENT_ALREADY_CANCELLED')
    const start=instant(a.startDateTime||a.start)
    if(start<=now())throw Error('MANAGEMENT_LINK_EXPIRED')
    return {name:a.customers[0].name||'',email:a.customers[0].emailAddress||'',start,end:instant(a.endDateTime||a.end)}
  }
  const digest = d => JSON.stringify([d.name,d.email,d.start,d.end])
  return {
    async inspect(token) {
      return ledger.exclusive(async tx=>{
        const {r}=record(token,tx)
        if(r.state==='cancelled')return {state:'cancelled',mail:mailer?.status(keyFrom(token,env))||'review'}
        if(r.state!=='confirmed')return {state:'review'}
        const data=await details(r), expires=now()+15*60000
        return {state:'confirmed',data,expires,proof:mac(token+':'+expires+':'+digest(data),env)}
      })
    },
    async cancel(token,body) {
      if(env.BOOKINGS_ALLOW_WRITES!=='true')throw Error('BOOKING_TEST_MODE')
      const expires=Number(body?.expires), reason=body?.reason||''
      if(!Number.isFinite(expires)||expires<now()||expires>now()+15*60000||typeof reason!=='string'||reason.length>600||/[<>\x00-\x08]/.test(reason))throw Error('INVALID_CONFIRMATION')
      return ledger.exclusive(async tx=>{
        const {key,r}=record(token,tx)
        if(r.state==='cancelled')return {state:'cancelled',mail:mailer?.status(keyFrom(token,env))||'review'}
        if(r.state!=='confirmed')return {state:'review'}
        const data=await details(r)
        if(!equal(body.proof,mac(token+':'+expires+':'+digest(data),env)))throw Error('INVALID_CONFIRMATION')
        if(!mailer)throw Error('CANCELLATION_MAIL_NOT_CONFIGURED')
        await mailer.prepare(key,data,reason.trim())
        // Persistent before the upstream write: never retry an ambiguous cancellation.
        tx.cancellation(key,'cancelling')
        try {
          await graph.call('/appointments/'+encodeURIComponent(r.appointmentId),undefined,'DELETE')
          tx.cancellation(key,'cancelled')
          try { mailer.wake() } catch { console.error('[CANCELLATION_MAIL] WAKE_FAILED') }
          return {state:'cancelled',mail:'pending'}
        } catch {
          tx.cancellation(key,'cancel_review')
          return {state:'review'}
        }
      })
    }
  }
}

