export function installManagementRoutes(router,getService,env) {
  router.use('/manage', (req,res,next)=>{
    res.set({'Referrer-Policy':'no-referrer','X-Robots-Tag':'noindex, nofollow','Content-Security-Policy':"default-src 'none'; style-src 'unsafe-inline'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'"})
    if(env.BOOKINGS_OWNER_MANAGEMENT!=='true')return res.sendStatus(404)
    next()
  })
  router.get('/manage/:token',async(req,res)=>{
    try {res.type('html').send(managementPage(await getService().inspect(req.params.token),req.params.token))}
    catch {res.status(400).type('html').send(managementPage({state:'error'}))}
  })
  router.post('/manage/:token',async(req,res)=>{
    if(req.headers.origin!==(env.BOOKINGS_SITE_ORIGIN||'https://cuisines-limetta.com')||req.headers['sec-fetch-site']==='cross-site')return res.sendStatus(403)
    try {const result=await getService().cancel(req.params.token,req.body);res.status(result.state==='review'?503:200).type('html').send(managementPage(result))}
    catch {res.status(400).type('html').send(managementPage({state:'error'}))}
  })
}

