import fs from 'node:fs'
import path from 'node:path'
import { managementLink, escapeHtml as esc, appointmentLabel } from './cancellation.js'
import { mailSender } from './mail-transport.js'

export function ownerMessage(data,key,env,owner) {
  if(!/^[^\s@<>]+@cuisines-limetta\.com$/i.test(owner||''))throw Error('INVALID_OWNER_EMAIL')
  const link=managementLink(key,env), date=appointmentLabel(data)
  return {from:{name:'Cuisines Limetta',address:mailSender(env)},to:owner,
    subject:`Rendez-vous confirmé — ${data.name.replace(/[\r\n]/g,' ')} — ${date}`,
    text:`${data.name}\n${date}\n${data.address}\n\nGérer ou annuler ce rendez-vous : ${link}\n\nLien privé réservé à Jordan, à ne pas transférer au client. Une confirmation sera demandée.`,
    html:`<div style="font:16px/1.6 Arial;color:#24336a;max-width:600px"><h1 style="font:30px Georgia">Un nouveau projet à rencontrer.</h1><p><strong>${esc(data.name)}</strong><br>${esc(date)}<br>${esc(data.address)}</p><p><a href="${esc(link)}" style="display:inline-block;padding:14px 20px;background:#24336a;color:white;border-radius:8px;text-decoration:none">Gérer ou annuler ce rendez-vous</a></p><p style="font-size:12px">Lien privé réservé à Jordan. Ne le transférez pas au client. Une confirmation sera demandée avant toute annulation.</p></div>`,
    messageId:`<gestion-${key}@cuisines-limetta.com>`,disableFileAccess:true,disableUrlAccess:true}
}
export function createOwnerNotifier({directory,ledgerPath,transport,env,owner,now=Date.now}) {
  if(env.BOOKINGS_OWNER_MANAGEMENT!=='true')return null
  const dir=path.join(directory,'owner');fs.mkdirSync(dir,{recursive:true,mode:0o700})
  let running=false
  return {
    prepare(key,data) {
      if(!/^[a-f0-9-]{36}$/i.test(key))throw Error('INVALID_REQUEST_ID')
      ownerMessage(data,key,env,owner)
      const f=path.join(dir,key+'.json')
      if(fs.existsSync(f))return
      fs.writeFileSync(f,JSON.stringify({state:'pending',created:now(),data}),{flag:'wx',mode:0o600})
    },
    async flush() {
      if(running)return
      running=true
      try {
        const ledger=fs.existsSync(ledgerPath)?JSON.parse(fs.readFileSync(ledgerPath,'utf8')):{}
        for(const file of fs.readdirSync(dir)) {
          if(!/^[a-f0-9-]{36}\.json$/i.test(file))continue
          const key=file.slice(0,-5), f=path.join(dir,file), entry=JSON.parse(fs.readFileSync(f,'utf8'))
          if(now()-entry.created>7*86400000){fs.unlinkSync(f);continue}
          if(entry.state!=='pending'||ledger[key]?.state!=='confirmed')continue
          if(new Date(entry.data.start).getTime()<=now())continue
          // Atomic claim across processes; interrupted attempts require review.
          const claim=f+'.claimed'
          try{fs.writeFileSync(claim,'',{flag:'wx',mode:0o600})}catch(e){if(e.code==='EEXIST')continue;throw e}
          fs.writeFileSync(f,JSON.stringify({state:'sending',created:entry.created}),{mode:0o600})
          try {
            const result=await transport.sendMail(ownerMessage(entry.data,key,env,owner))
            if(!result.accepted?.length||result.rejected?.length)throw Error('OWNER_MAIL_NOT_ACCEPTED')
            fs.writeFileSync(f,JSON.stringify({state:'accepted',created:entry.created}),{mode:0o600})
          } catch {fs.writeFileSync(f,JSON.stringify({state:'review',created:entry.created}),{mode:0o600});console.error('[BOOKING_OWNER_MAIL] REQUIRES_REVIEW')}
        }
      } finally {running=false}
    }
  }
}

