import fs from 'node:fs'
import path from 'node:path'
import {fileURLToPath} from 'node:url'
import {createMailTransport,mailSender} from './mail-transport.js'
import {renderCancellation} from './cancellation-template.js'

export function createCancellationMailer(env=process.env,options={}) {
  const root=fileURLToPath(new URL('../',import.meta.url))
  const directory=options.directory||path.join(root,'.booking-state','cancellations')
  const ledgerPath=options.ledgerPath||path.join(root,'.booking-state','requests.json')
  const site=options.site||JSON.parse(fs.readFileSync(path.join(root,'content.json'))).site
  const logo=options.logo||fs.readFileSync(new URL('./email-logo.png',import.meta.url))
  const transport=options.transport||createMailTransport(env),now=options.now||Date.now
  fs.mkdirSync(directory,{recursive:true,mode:0o700})
  let running=false
  const file=key=>{if(!/^[a-f0-9-]{36}$/i.test(key))throw Error('INVALID_REQUEST_ID');return path.join(directory,key+'.json')}
  function save(key,data){const f=file(key),tmp=f+'.tmp';fs.writeFileSync(tmp,JSON.stringify(data),{mode:0o600});fs.renameSync(tmp,f)}
  function message(key,data,reason){return {from:{name:'Cuisine Limetta',address:mailSender(env)},to:{name:data.name,address:data.email},replyTo:site.emailContact,...renderCancellation(data,site,'cid:limetta-logo',reason),messageId:`<annulation-${key}@cuisines-limetta.com>`,attachments:[{filename:'logo-limetta.png',content:logo,contentType:'image/png',cid:'limetta-logo'}],disableFileAccess:true,disableUrlAccess:true}}
  function status(key){if(!fs.existsSync(file(key)))return 'missing';const state=JSON.parse(fs.readFileSync(file(key))).state;return state==='sending'?'review':state}
  async function flush(){
    if(running)return
    running=true
    try{
      const ledger=fs.existsSync(ledgerPath)?JSON.parse(fs.readFileSync(ledgerPath)):{}
      for(const name of fs.readdirSync(directory)){
        if(!/^[a-f0-9-]{36}\.json$/i.test(name))continue
        const key=name.slice(0,-5),entry=JSON.parse(fs.readFileSync(file(key)))
        if(now()-entry.created>7*86400000){if(entry.data){save(key,{state:'review',created:entry.created});console.error('[CANCELLATION_MAIL] EXPIRED_REQUIRES_REVIEW')}continue}
        if(entry.state!=='pending'||ledger[key]?.state!=='cancelled')continue
        // The claim is never cleared: a lost provider response must not trigger a second email.
        try{fs.writeFileSync(file(key)+'.claim','',{flag:'wx',mode:0o600})}catch(e){if(e.code==='EEXIST')continue;throw e}
        save(key,{state:'sending',created:entry.created})
        try{
          const result=await transport.sendMail(message(key,entry.data,entry.reason))
          if(!result.accepted?.length||result.rejected?.length)throw Error('MAIL_NOT_ACCEPTED')
          save(key,{state:'accepted',created:entry.created})
        }catch{save(key,{state:'review',created:entry.created});console.error('[CANCELLATION_MAIL] REQUIRES_REVIEW')}
      }
    }finally{running=false}
  }
  const wake=()=>{void flush().catch(()=>console.error('[CANCELLATION_MAIL] STORAGE_REQUIRES_REVIEW'))}
  const timer=options.auto===false?null:setInterval(wake,30000);timer?.unref();if(timer)wake()
  return {
    async prepare(key,data,reason){
      if(!/^[^\s@<>\r\n]+@[^\s@<>]+\.[^\s@<>]+$/.test(data.email||''))throw Error('INVALID_CUSTOMER_EMAIL')
      message(key,data,reason);await transport.verify()
      if(fs.existsSync(file(key)))throw Error('CANCELLATION_ALREADY_PREPARED')
      fs.writeFileSync(file(key),JSON.stringify({state:'pending',created:now(),data,reason}),{flag:'wx',mode:0o600})
    },
    status,flush,wake,close(){if(timer)clearInterval(timer);transport.close?.()}
  }
}
